from wcommon import dims_G, dims_M, legend, notes, head, sched
from wmodel import G, M
LAYER = "E-LIGHT"
def _trk(s,p1,p2,n):
    pts=[(p1[0]+(p2[0]-p1[0])*(i+0.5)/n,p1[1]+(p2[1]-p1[1])*(i+0.5)/n) for i in range(n)]; s.track([p1,p2],pts); return pts
ROWS=[(lambda s,x,y: s.track([(x-0.3,y),(x+0.3,y)],[(x-0.15,y),(x+0.15,y)]), "تراك لايت أسود 3 فاز مع سبوت LED 15W 3000K زاوية 36°", "black track + LED spots 15W 3000K"),
      (lambda s,x,y: s.led_panel(x,y,0.3,0.3), "لوحة LED 60×60 سم 40W 4000K (شمسي)", "LED panel 60x60 40W 4000K"),
      (lambda s,x,y: s.downlight(x,y,0.1), "سبوت لايت مثبت 12W 4000K", "downlight 12W 4000K"),
      (lambda s,x,y: s.strip((x-0.3,y),(x+0.3,y)), "شريط LED 12V 2700K تحت الدرج / خلف اللوحات", "LED strip 12V 2700K"),
      (lambda s,x,y: s.rect(x-0.3,y-0.1,x+0.3,y+0.1,color=1), "لوحة مضيئة / نيون (حسب ملف المواصفات)", "lightbox / neon sign"),
      (lambda s,x,y: s.box_label(x,y,"EX",h=0.08,w=0.35,color=3), "لوحة خروج طوارئ LED مع بطارية", "emergency exit sign")]
def draw_G(s):
    spots=_trk(s,(9.75,35.6),(9.75,43.2),8)+_trk(s,(14.0,35.6),(14.0,43.2),8)+_trk(s,(10.4,41.9),(13.9,41.9),4)
    s.text(9.85,43.35,"تراك T1 - 7.6 م - 8 سبوت",h=0.09); s.text(13.0,43.35,"تراك T2 - 7.6 م - 8 سبوت",h=0.09); s.text(11.0,42.1,"تراك T3 - 3.5 م",h=0.09)
    pan=[(x,y) for x in (10.2,11.85,13.5) for y in (44.5,46.3,48.1)]+[(11.85,49.8),(13.6,49.8)]+[(x,y) for x in (10.3,11.85,13.4) for y in (51.5,53.3)]
    for p in pan: s.led_panel(*p,0.6,0.6)
    s.strip((9.4,36.5),(9.4,41.4)); s.text(8.4,38.9,"LED strip تحت كل درجة (13 درجة)",h=0.09,rotation=90)
    for r,t in [((12.4,35.15,13.6,35.3),"نيون We Chicks 0.8×0.3"),((10.0,43.45,14.3,43.6),"لوحة ORDER HERE مضيئة 4.5×0.7 م"),((14.25,36.6,14.4,37.3),"نيون PICK IT UP"),((14.25,41.0,14.4,42.5),"لوحة المنيو مضيئة 1.5×2.2")]:
        s.rect(*r,color=1); s.text(r[0],r[3]+0.05,t,h=0.09,color=1)
    for y in (37.4,37.9,38.4,38.9): s.circle(9.45,y,0.13,color=1)
    s.text(8.3,39.2,"4 أيقونات دائرية مضيئة Ø30",h=0.09,color=1,attach=3)
    s.box_label(13.2,35.35,"EX",h=0.09,w=0.4,color=3); s.box_label(14.0,43.75,"EX",h=0.09,w=0.4,color=3)
    s.dim((9.3,35.6),(9.75,35.6),offset=1.6); s.dim((14.0,35.6),(14.4,35.6),offset=1.6); s.dim((9.75,35.6),(9.75,43.2),offset=-1.9,horizontal=False)
    dims_G(s,[(10.2,44.5),(11.85,44.5),(13.5,44.5),(10.2,46.3),(10.2,48.1),(10.3,51.5),(11.85,51.5),(13.4,51.5),(10.3,53.3)])
    legend(s,"G","رموز الإنارة - LIGHTING LEGEND",ROWS)
    sched(s,"G","جدول الإنارة والكميات - الأرضي",["البند","المواصفة","العدد"],[("تراك لايت","مسار ألمنيوم أسود 3 فاز: 7.6+7.6+3.5 م","18.7 م"),("سبوت تراك","LED 15W 3000K CRI90 زاوية 36° أسود",f"{len(spots)}"),
        ("لوحات LED","60×60 40W 4000K شمسي IP40 (مطبخ/غسيل/تحضير)",f"{len(pan)}"),("شريط LED","12V 2700K 10W/م تحت درجات الدرج","13 م"),("نيون/لوحات","We Chicks + ORDER HERE + PICK IT UP + منيو","4"),
        ("أيقونات","دائرية مضيئة Ø30 سم","4"),("طوارئ","لوحة خروج + كشاف طوارئ","2+3"),("الحمل الكلي","20×15 + 17×40 + 130 + 450 W","~1.3 kW")])
    notes(s,"G",["إنارة الصالة بتراك لايت أسود على السقف المكشوف الأسود، سبوتات 3000K دافئة موجهة على الجدران والطاولات (حسب الرندر).",
        "المطبخ والتحضير لوحات LED 60×60 بلون شمسي 4000K داخل السقف المستعار بشدة إضاءة 500 لوكس.","دوائر الإنارة على مفاتيح قرب الكاشير، النيون واللوحات على مؤقت.","الأبعاد الحمراء: مواقع التراكات ولوحات LED عن الجدران."],"ملاحظات الإنارة")
    head(s,"G","مخطط الإنارة - الدور الأرضي: تراك لايت أسود في الصالة، لوحات LED 60×60 شمسي بالمطبخ، شريط LED بالدرج، نيون ولوحات مضيئة.")
def draw_M(s):
    spots=_trk(s,(0.7,18.3),(8.3,18.3),8)+_trk(s,(0.7,21.3),(8.3,21.3),8)+_trk(s,(1.6,17.0),(5.0,17.0),4)
    s.text(0.8,18.45,"تراك T4 - 7.6 م - 8 سبوت",h=0.09); s.text(0.8,21.45,"تراك T5 - 7.6 م - 8 سبوت",h=0.09); s.text(1.7,17.15,"تراك البار T6 - 3.4 م",h=0.09)
    dl=[(1.5,24.0),(4.0,24.0),(6.5,24.0),(1.0,27.0),(2.5,26.3),(4.2,26.6),(5.8,27.0),(7.2,26.3),(9.8,26.8),(2.3,24.3)]
    for p in dl: s.downlight(*p,0.1)
    pan=[(x,23.3) for x in (10.5,13.0,15.5,18.0,20.5)]+[(15.4,19.0),(15.4,17.2),(19.0,19.0),(21.0,19.0),(19.0,17.2),(16.5,14.6),(18.5,14.6),(20.5,14.6),(16.5,15.6)]
    for p in pan: s.led_panel(*p,0.6,0.6)
    bat=[(20.3,21.0),(19.5,26.8),(21.5,26.8),(13.5,26.6)]
    for p in bat: s.rect(p[0]-0.6,p[1]-0.06,p[0]+0.6,p[1]+0.06,color=6)
    s.text(19.5,27.0,"كشاف LED 36W IP65 بالمستودع والتجميد والسيرفر",h=0.09)
    s.rect(0.15,18.2,0.3,21.2,color=1); s.text(-0.1,21.3,"نيون HI CHICKS FRIENDS 3.0 م",h=0.09,color=1,attach=3)
    s.rect(8.55,21.0,8.7,22.6,color=1); s.text(8.5,22.7,"نيون ابتسامة على جدار البلاط الأحمر",h=0.09,color=1,attach=3)
    for p in [(0.5,23.1),(8.6,24.9),(13.8,21.3)]: s.box_label(*p,"EX",h=0.09,w=0.4,color=3)
    s.dim((0.1,18.3),(0.7,18.3),offset=0.5); s.dim((0.7,18.3),(0.7,21.3),offset=-0.5,horizontal=False); s.dim((0.1,21.3),(0.1,23.0),offset=-1.9,horizontal=False)
    dims_M(s,dl[:3]+pan[:5]+[pan[5],pan[7],pan[10]])
    legend(s,"M","رموز الإنارة - LEGEND",ROWS)
    sched(s,"M","الإنارة - الميزانين",["البند","المواصفة","العدد"],[("تراك","أسود 7.6+7.6+3.4 م","18.6 م"),("سبوت","LED 15W 3000K",f"{len(spots)}"),("داون لايت","12W 4000K ممر+حمامات",f"{len(dl)}"),("لوحات LED","60×60 40W 4000K مكاتب",f"{len(pan)}"),("كشافات","36W IP65",f"{len(bat)}"),("نيون","HI CHICKS + ابتسامة","2"),("طوارئ","لوحات خروج","3")])
    notes(s,"M",["تراك لايت أسود على السقف الأسود المكشوف بالجلسات والبار 3000K.","المكاتب وغرفة الاجتماعات لوحات LED 4000K شمسي 500 لوكس.","الأبعاد الحمراء: التراكات والداون لايت ولوحات LED عن الجدران."],"ملاحظات")
    head(s,"M","مخطط الإنارة - الميزانين: تراك لايت بالجلسات والبار، داون لايت بالممر والحمامات، لوحات LED 4000K بالمكاتب، نيون الجدران.")
